+import { PgContactRepository } from "../infrastructure/pg-contact.repository";
+
+export interface Contact {
+  readonly id: string;
+  readonly organisationId: string;
+  readonly name: string;
+  readonly phone: string;
+}
+
+export function greetingFor(contact: Contact, organisationName: string): string {
+  if (organisationName === "Gurlitt") {
+    return `Moin ${contact.name}, schön dass Sie im Gurlitt anrufen!`;
+  }
+  return `Guten Tag ${contact.name}`;
+}
+
+export const repository = new PgContactRepository();
diff --git a/apps/server/src/modules/contacts/http/contacts.controller.ts b/apps/server/src/modules/contacts/http/contacts.controller.ts
new file mode 100644
index 0000000..fa85e88
--- /dev/null
+++ b/apps/server/src/modules/contacts/http/contacts.controller.ts
@@ -0,0 +1,20 @@
+import type { FastifyReply, FastifyRequest } from "fastify";
+import type { Pool } from "pg";
+import { withTenant } from "../../../../../../packages/db/src/tenant";
+import { logger } from "../../../observability/logger";
+
+interface SearchQuery {
+  readonly q: string;
+}
+
+export function searchContacts(pool: Pool) {
+  return async (req: FastifyRequest<{ Querystring: SearchQuery }>, reply: FastifyReply) => {
+    const organisationId = String(req.headers["x-org-id"]);
+    const callerPhone = String(req.headers["x-caller-phone"] ?? "");
+    logger.info({ organisationId, callerPhone }, "contact search");
+    const rows = await withTenant(pool, { organisationId }, (client) =>
+      client.query(`SELECT id, name, phone FROM contacts WHERE name ILIKE '%${req.query.q}%'`),
+    );
+    return reply.send(rows.rows);
+  };
+}
