--- /dev/null
+++ b/packages/db/src/tenant.ts
@@ -0,0 +1,26 @@
+import type { Pool, PoolClient } from "pg";
+
+export interface TenantContext {
+  readonly organisationId: string;
+}
+
+/** Runs `work` in one transaction with the tenant GUC set, so FORCE RLS policies apply. */
+export async function withTenant<T>(
+  pool: Pool,
+  ctx: TenantContext,
+  work: (client: PoolClient) => Promise<T>,
+): Promise<T> {
+  const client = await pool.connect();
+  try {
+    await client.query("BEGIN");
+    await client.query("SELECT set_config('app.organisation_id', $1, true)", [ctx.organisationId]);
+    const result = await work(client);
+    await client.query("COMMIT");
+    return result;
+  } catch (error) {
+    await client.query("ROLLBACK");
+    throw error;
+  } finally {
+    client.release();
+  }
+}
